class Twitter {
    unordered_map<int, vector<pair<int,int>>> tweets;
    unordered_map<int, unordered_set<int>> follows;
    int time = 0;
public:
    Twitter() {}

    void postTweet(int userId, int tweetId) {
        tweets[userId].insert(tweets[userId].begin(), {++time, tweetId});
    }

    vector<int> getNewsFeed(int userId) {
        priority_queue<tuple<int,int,int,int>> pq;
        auto consider = [&](int u) {
            if (!tweets[u].empty()) {
                auto &[t, tid] = tweets[u][0];
                pq.push({t, tid, u, 0});
            }
        };
        consider(userId);
        for (int u : follows[userId]) consider(u);
        vector<int> res;
        while (!pq.empty() && (int)res.size() < 10) {
            auto [t, tid, u, idx] = pq.top(); pq.pop();
            res.push_back(tid);
            if (idx + 1 < (int)tweets[u].size()) {
                auto &[nt, ntid] = tweets[u][idx + 1];
                pq.push({nt, ntid, u, idx + 1});
            }
        }
        return res;
    }

    void follow(int followerId, int followeeId) {
        follows[followerId].insert(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        follows[followerId].erase(followeeId);
    }
};

