class Twitter {
    private Map<Integer, List<int[]>> tweets = new HashMap<>();
    private Map<Integer, Set<Integer>> follows = new HashMap<>();
    private int time = 0;

    public Twitter() {}

    public void postTweet(int userId, int tweetId) {
        tweets.computeIfAbsent(userId, k -> new ArrayList<>()).add(0, new int[]{++time, tweetId});
    }

    public List<Integer> getNewsFeed(int userId) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        Set<Integer> people = follows.getOrDefault(userId, new HashSet<>());
        List<Integer> ids = new ArrayList<>(people);
        ids.add(userId);
        for (int u : ids) {
            List<int[]> tl = tweets.get(u);
            if (tl != null && !tl.isEmpty()) pq.offer(new int[]{tl.get(0)[0], tl.get(0)[1], u, 0});
        }
        List<Integer> res = new ArrayList<>();
        while (!pq.isEmpty() && res.size() < 10) {
            int[] top = pq.poll();
            res.add(top[1]);
            List<int[]> tl = tweets.get(top[2]);
            if (top[3] + 1 < tl.size()) {
                int[] nx = tl.get(top[3] + 1);
                pq.offer(new int[]{nx[0], nx[1], top[2], top[3] + 1});
            }
        }
        return res;
    }

    public void follow(int followerId, int followeeId) {
        follows.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> s = follows.get(followerId);
        if (s != null) s.remove(followeeId);
    }
}

