    this.follows = new Map();
    this.time = 0;
};

Twitter.prototype.postTweet = function(userId, tweetId) {
    if (!this.tweets.has(userId)) this.tweets.set(userId, []);
    this.tweets.get(userId).unshift([++this.time, tweetId]);
};

Twitter.prototype.getNewsFeed = function(userId) {
    const people = new Set(this.follows.get(userId) || []);
    people.add(userId);
    const heap = [];
    for (const u of people) {
        const tl = this.tweets.get(u);
        if (tl && tl.length) heap.push([tl[0][0], tl[0][1], u, 0]);
    }
    heap.sort((a, b) => b[0] - a[0]);
    const res = [];
    while (heap.length && res.length < 10) {
        const [t, tid, u, idx] = heap.shift();
        res.push(tid);
        const tl = this.tweets.get(u);
        if (idx + 1 < tl.length) {
            const nx = tl[idx + 1];
            heap.push([nx[0], nx[1], u, idx + 1]);
            heap.sort((a, b) => b[0] - a[0]);
        }
    }
    return res;
};

